param([string]$Dir, [string]$GenImage = $env:GEN_IMAGE, [string[]]$Only = @())
# The session-header scene's art: one sheet of monsters (one per background scene, plus a golem) and one of camp props.
# Each is a 4x2 grid on magenta, cut like the character sheets (scene_sprites.py).
if (-not $GenImage) { throw "Pass -GenImage <your image script> or set GEN_IMAGE" }
$style = "TRUE pixel art: chunky equal square pixels on a strict grid, clean 1-pixel dark outline, flat colors with 2-3 tone cel shading, no anti-aliasing, no blur, no gradients. Plain solid flat pure magenta background (#ff00ff) everywhere, nothing pink, purple or magenta in the art itself, no ground shadows, no magic effects, no speech bubbles, no text, no letters, no numbers, no labels, no UI, no border."
$tasks = @(
 @('sheet_monsters', "A pixel art sprite sheet of EIGHT different cute fantasy monsters for a 16-bit SNES-era JRPG side-view battle, every monster facing LEFT (side or three-quarter view), arranged in a neat grid of 4 columns by 2 rows with generous empty space between them, all at the SAME pixel scale, each standing on the same baseline within its row. Top row, left to right: 1 a small teal-green dragon (wyvern) with wings spread, hovering; 2 a round translucent blue slime with big eyes and a shiny highlight; 3 a glowing pale-blue will-o'-wisp spirit flame with a small ghostly face; 4 a white frost wolf with icy blue fur tips, crouched and growling. Bottom row, left to right: 5 a grumpy walking tree stump monster with orange autumn leaves on top and root legs; 6 a mimic: a wooden treasure chest monster with its lid open showing sharp white teeth and a long red tongue; 7 a teal lake serpent rising from a small splash of blue water; 8 a mossy grey stone golem with glowing yellow eyes. Cute but menacing chibi monsters. Sizes in art-pixels: dragon about 34 tall, golem about 34 tall, wolf about 24 tall and 34 wide, serpent about 32 tall, stump about 30 tall, mimic about 22 tall, slime about 16 tall, wisp about 20 tall. $style"),
 @('sheet_props', "A pixel art sprite sheet of EIGHT camping and adventure props for a 16-bit SNES-era JRPG, side view, arranged in a neat grid of 4 columns by 2 rows with generous empty space between them, all at the SAME pixel scale, each standing on the same baseline within its row. Top row, left to right: 1 an UNLIT campfire: three crossed brown logs inside a small ring of grey stones, no fire, no smoke (about 18 art-pixels wide, 8 tall); 2 a small black iron cooking pot full of stew hanging from a wooden tripod (about 18 art-pixels tall); 3 a canvas A-frame camping tent with its front flap tied open, cream canvas and brown poles (about 30 art-pixels tall, 40 wide); 4 a closed wooden treasure chest with gold trim (about 14 art-pixels tall, 18 wide). Bottom row, left to right: 5 an open wooden treasure chest full of gold coins and one blue gem (about 16 art-pixels tall, 18 wide); 6 a rolled-out blue sleeping bag with a white pillow, lying flat (about 7 art-pixels tall, 28 wide); 7 a wooden signpost with two blank arrow boards, no writing (about 26 art-pixels tall); 8 a brown leather backpack with a rolled blanket strapped on top (about 14 art-pixels tall). $style")
)
if ($Only.Count) { $tasks = @($tasks | Where-Object { $Only -contains $_[0] }) }
$jobs = foreach ($t in $tasks) {
  Start-Job -Name $t[0] { param($g, $p, $o) & $g -Prompt $p -Out $o -Shape 'landscape' } -ArgumentList $GenImage, $t[1], (Join-Path $Dir "$($t[0]).png")
}
$jobs | Wait-Job | ForEach-Object { "{0}: {1}" -f $_.Name, ((Receive-Job $_ 2>&1 | Out-String).Trim() -split "`n" | Select-Object -Last 1); Remove-Job $_ }
